export const api = { 
    get: async (path) => 
        { 
        const res = await fetch(path, { method: 'GET', credentials: 'include' }); 
        if (!res.ok) throw new Error('API error'); 
        return res.json(); 
        }, 
    post: async (path, body) => 
        { 
            const res = await fetch
            (path, 
                { 
                method: 'POST', 
                headers: { 'Content-Type': 'application/json' }, 
                credentials: 'include', body: JSON.stringify(body), 
                }
            ); 
            if (!res.ok) throw new Error('API error'); 
            return res.json(); 
        } 
    };

export async function fetchMachineBySerial(serial) {
  // Подстраивайтесь под реальный путь вашего бекенда
  const url = `/api/machines/?serial_number_machine=${encodeURIComponent(serial)}`;

  const res = await fetch(url, {
    credentials: 'include',
  });

  if (!res.ok) {
    // 404/400 — наличие ошибки не найдено
    return null;
  }

  const data = await res.json();

  // Если бекенд возвращает массив, возьмем первый элемент
  if (Array.isArray(data)) {
    return data[0] ?? null;
  }
  return data;
}
